def distancia_edicion(a: str, b: str) -> int:
    if len(a) < len(b):
        a, b = b, a

    prev = list(range(len(b) + 1))

    for i, ca in enumerate(a, start=1):
        curr = [i] + [0] * len(b)

        for j, cb in enumerate(b, start=1):
            if ca == cb:
                curr[j] = prev[j - 1]
            else:
                curr[j] = 1 + min(
                    prev[j],      # borrado
                    curr[j - 1],  # inserción
                    prev[j - 1]   # sustitución
                )

        prev = curr

    return prev[-1]

def fusionar(intervalos):
    if not intervalos:
        return []

    # Normalizamos por si algún intervalo viene con inicio > fin
    normalizados = [(min(a, b), max(a, b)) for a, b in intervalos]

    # Ordenamos por inicio y luego por fin
    normalizados.sort()

    fusionados = []

    for inicio, fin in normalizados:
        if not fusionados:
            fusionados.append((inicio, fin))
        else:
            ultimo_inicio, ultimo_fin = fusionados[-1]

            # Si se solapan o se tocan, los unimos
            if inicio <= ultimo_fin:
                fusionados[-1] = (ultimo_inicio, max(ultimo_fin, fin))
            else:
                fusionados.append((inicio, fin))

    return fusionados

def siguiente_permutacion(lista):
    a = list(lista)
    n = len(a)

    if n <= 1:
        return a

    i = n - 2
    while i >= 0 and a[i] >= a[i + 1]:
        i -= 1

    if i < 0:
        return sorted(a)

    j = n - 1
    while a[j] <= a[i]:
        j -= 1

    a[i], a[j] = a[j], a[i]
    a[i + 1:] = reversed(a[i + 1:])

    return a

import heapq

def dijkstra(grafo, origen):
    distancias = {origen: 0}
    cola = [(0, origen)]

    while cola:
        distancia_actual, nodo = heapq.heappop(cola)

        if distancia_actual > distancias.get(nodo, float("inf")):
            continue

        for vecino, peso in grafo.get(nodo, []):
            nueva_distancia = distancia_actual + peso

            if nueva_distancia < distancias.get(vecino, float("inf")):
                distancias[vecino] = nueva_distancia
                heapq.heappush(cola, (nueva_distancia, vecino))

    return distancias

def islas(matriz):
    if not matriz:
        return 0

    visitadas = set()
    total = 0

    for i, fila in enumerate(matriz):
        for j, valor in enumerate(fila):
            if valor == 1 and (i, j) not in visitadas:
                total += 1
                pila = [(i, j)]
                visitadas.add((i, j))

                while pila:
                    x, y = pila.pop()

                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy

                        if (
                            0 <= nx < len(matriz)
                            and 0 <= ny < len(matriz[nx])
                            and (nx, ny) not in visitadas
                            and matriz[nx][ny] == 1
                        ):
                            visitadas.add((nx, ny))
                            pila.append((nx, ny))

    return total
